css:
/* ============ _variables.scss — дополнения в :root ============ */
:root {
  /* радиусы: --radius-3/4 уже есть, добавляем недостающие ступени */
  --radius-1: 8px;
  --radius-2: 12px;
  --radius-pill: 999px;

  /* шкала интервалов (в файле сегодня НЕТ ни одной переменной интервала) */
  --sp-1: 4px;  --sp-2: 8px;  --sp-3: 12px; --sp-4: 16px;
  --sp-5: 24px; --sp-6: 32px; --sp-7: 48px;
  --sp-section: var(--sp-6);   /* раздел→раздел 32 против 24 внутри списка */

  /* шкала кегля: 7 ступеней вместо 11 фактических */
  --fs-display-1: 30px; /* H1 мастхеда, Oswald 700 */
  --fs-display-2: 20px; /* заголовок-хребет (расписание), Oswald 600 */
  --fs-title: 18px;     /* название события в строке расписания */
  --fs-body: 15px;      /* проза, строки-выходы */
  --fs-meta: 13px;      /* время, цена, возраст, счётчики */
  --fs-label: 12px;     /* секционные метки 2-го ранга, uppercase */
  --fs-micro: 11px;     /* месяц/день недели */

  /* синий как ТЕКСТ: --c-primary-600 (#257ED8) даёт 3.91:1 — фейл AA */
  --c-primary-600-text: 30 99 198;  /* #1E63C6, 5.2:1 на --c-bg */

  /* текст на постоянной оранжевой заливке: заливка не меняется по темам,
     значит и текст на ней постоянен (--c-charcoal здесь ловушка) */
  --c-on-accent: 26 26 26;
}
:root.dark {
  --c-primary-600-text: 96 165 250;  /* 7.9:1 на #0B0B0C */
  --c-on-accent: 26 26 26;           /* НЕ инвертировать */
}

/* ============ _ui.scss — знаки перехода ============ */
.lnk {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  font: 600 var(--fs-body)/1.35 var(--font-body);
  color: rgb(var(--c-ink));
  text-decoration: none;
}
.lnk > svg { flex: none; width: 14px; height: 14px; stroke: currentColor; fill: none; }
.lnk--back { color: rgb(var(--c-muted)); font-weight: 500; font-size: var(--fs-meta); }
.lnk--back > svg { order: -1; }
.lnk--int > svg { opacity: .55; margin-left: auto; }
.lnk--ext { color: rgb(var(--c-muted)); }
.lnk--ext > svg { width: 16px; height: 16px; }
/* строка-выход в хвосте: цель ≥44px даёт padding, а не кегль */
.lnk--row {
  display: flex; width: 100%; min-height: 50px;
  padding-block: var(--sp-3);
  border-top: 1px solid rgb(var(--c-line) / var(--line-alpha));
}
@media (hover: hover) { .lnk:hover { color: rgb(var(--c-accent-orange-text)); } }

/* ============ _ui.scss — сегментированный контрол (один на приложение) ============ */
.ui-seg {
  display: inline-flex; gap: 2px; padding: 3px;
  border-radius: var(--radius-pill);
  background: rgb(var(--c-ink) / 0.05);
}
.ui-seg__btn {
  min-height: 44px; padding: 0 14px; border: 0;
  border-radius: var(--radius-pill);
  font: 600 var(--fs-meta)/1 var(--font-body);
  color: rgb(var(--c-ink) / 0.62);
  background: transparent;
}
.ui-seg__btn.is-active {
  background: rgb(var(--c-surface));
  color: rgb(var(--c-accent-orange-text));
  box-shadow: var(--shadow-soft);
}
:root.dark .ui-seg__btn.is-active { background: rgb(var(--c-ink) / 0.16); }
@media (min-width: 768px) { .ui-seg__btn { min-height: 38px; } }
/* тихая текстовая кнопка того же семейства — «показать прошедшие» */
.ui-seg-link {
  border: 0; background: none; min-height: 44px;
  font: 600 var(--fs-meta)/1 var(--font-body);
  color: rgb(var(--c-ink) / 0.62);
}
.ui-seg-link:hover { text-decoration: underline; }

/* ============ _ui.scss — кнопка (поднята из .mt__btn эталона) ============ */
.ui-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--sp-2);
  min-height: 46px; padding: 13px 18px;
  border: 1px solid rgb(var(--c-line) / 0.18);
  border-radius: var(--radius-2);
  font: 700 14.5px/1 var(--font-body);
  background: transparent; color: rgb(var(--c-ink));
}
.ui-btn--accent {
  background: rgb(var(--c-accent-orange));
  border-color: transparent;
  color: rgb(var(--c-on-accent));   /* 7.4:1 в обеих темах */
}

/* ============ _ui.scss — три ступени текста вместо шести альф ============ */
.tx-1 { color: rgb(var(--c-ink)); }
.tx-2 { color: rgb(var(--c-ink) / 0.86); }
.tx-3 { color: rgb(var(--c-muted)); }
